function resolvedTheme(pref=prefs.theme,systemDark=typeof matchMedia==='function'&&matchMedia('(prefers-color-scheme: dark)').matches){return pref==='system'?(systemDark?'dark':'light'):pref==='light'?'light':'dark'}
function applyPrefs(){if(!document.body)return;document.body.dataset.theme=resolvedTheme();document.body.dataset.textSize=prefs.text;document.documentElement.style.colorScheme=resolvedTheme();let meta=document.querySelector('meta[name=theme-color]');if(meta)meta.content=resolvedTheme()==='dark'?'#101313':'#f5f1e8';let toggle=$('#appearance');if(toggle)toggle.title=tr('Pengaturan tampilan','Display settings');if(toggle)toggle.setAttribute('aria-label',tr("Pengaturan tampilan · ","Display settings · ")+prefs.theme)}
