function status(){const el=$('#sync');if(!el)return;let msg=storageError?tr("Penyimpanan HP gagal","Device storage failed"):demo?tr("MODE UJI · lokal","TEST MODE · local"):closed()&&state.queue.length?tr("Tutup · data belum terkirim","Closed · data not yet sent"):state.queue.length?`${tr("Menunggu sinkron (","Awaiting sync (")}${state.queue.length})`:serverChecked?tr("Data tersinkron","Data synced"):tr("Menghubungkan…","Connecting…");el.textContent=storageError||demo?msg:'';let profileEl=$('#profileSync');if(profileEl)profileEl.textContent=msg;updateCompletionStatus()}
function toast(t){const e=$('#toast');e.textContent=t;e.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.style.display='none',2300)}
function enqueue(type,payload){if(demo)return;state.queue=state.queue.filter(e=>e.type!==type||e.person.id!==state.person.id);const event={id:uuid(),rev:++state.revision,type,person:{...state.person},payload};state.queue.push(event);if(type==='word'&&payload.found.length===20){state.wordCompletionEvent=event.id;state.wordCompletionAck=null}save();if(type==='assessment'||type==='word'&&payload.found.length===20)retryAt=0;scheduleSync()}
function jsonp(params){return new Promise((resolve,reject)=>{let cb='mg_'+uuid().replace(/-/g,''),s=document.createElement('script');let timer=setTimeout(()=>finish(null,new Error('timeout')),12000);function finish(v,e){clearTimeout(timer);delete window[cb];s.remove();e?reject(e):resolve(v)}window[cb]=v=>finish(v);s.onerror=()=>finish(null,new Error('network'));s.src=CONFIG.endpoint+'?'+new URLSearchParams({...params,callback:cb,t:Date.now()});document.head.append(s)})}
async function clock(){if(demo)return;try{let r=await jsonp({action:'status'});if(r.ok&&Number.isFinite(r.now)){clockOffset=r.now-Date.now();serverChecked=true;serverClosed=r.closed;status();if(closed()||app.querySelector('.closed'))render()}}catch{status()}}
function scheduleSync(){if(demo||syncing||Date.now()<retryAt||!navigator.onLine||!state.queue.length||(closed()&&closedAcked))return;setTimeout(sync,300+Math.random()*1800)}
async function sync(){if(syncing||demo||!state.queue.length||!navigator.onLine||Date.now()<retryAt)return;syncing=true;let batch=state.queue.slice(0,3);try{let ack=await jsonp({action:'ack',ids:batch.map(e=>e.id).join(',')});if(!ack.ok)throw Error('ack');const applyAck=r=>{let ids=new Set(r.received||[]);if(state.wordCompletionEvent&&ids.has(state.wordCompletionEvent)&&state.wordEnd&&state.found.length===20){state.wordCompletionAck=state.wordCompletionEvent}state.queue=state.queue.filter(e=>!ids.has(e.id));if(Number.isFinite(r.now)){clockOffset=r.now-Date.now();serverChecked=true;serverClosed=r.closed}save()};applyAck(ack);if(closed())closedAcked=true;batch=batch.filter(e=>state.queue.some(x=>x.id===e.id));if(batch.length&&!closed()){await fetch(CONFIG.endpoint,{method:'POST',mode:'no-cors',headers:{'Content-Type':'text/plain;charset=UTF-8'},body:JSON.stringify({events:batch}),redirect:'follow'});await new Promise(r=>setTimeout(r,1000));let r=await jsonp({action:'ack',ids:batch.map(e=>e.id).join(',')});if(!r.ok)throw Error('ack');applyAck(r);if(batch.some(e=>state.queue.some(x=>x.id===e.id)))throw Error('unconfirmed')}retryAt=Date.now()+20000}catch{retryAt=Date.now()+20000+Math.random()*20000}finally{syncing=false;status();if(closed()&&!app.querySelector('.closed'))render()}}
