function route(){return location.hash.slice(1)||'home'}function go(r){if(route()===r)render();else requestRoute(r)}function nav(t){return `${tr("<div class=\"navline\"><a class=\"back-big\" href=\"#home\">← Kembali</a><span class=\"eyebrow\" style=\"margin:0\">","<div class=\"navline\"><a class=\"back-big\" href=\"#home\">← Back</a><span class=\"eyebrow\" style=\"margin:0\">")}${t}</span></div>`}function name(){return esc(state.person?.name||'')}
