function shell(){let r=route(),active=!!state.person&&!closed();if(document.body){applyPrefs();document.body.dataset.route=active?r:closed()?'closed':'registration'}let b=$('#bottomNav');if(!b)return;b.hidden=!active||r==='magazine'||welcomePending;b.innerHTML=active?[["home","Home"],["magazine","Guide"],["thinking","Discover"],["word","Challenge"]].map(([key,label])=>`<a href="#${key}" ${key===r?'aria-current="page"':''}>${icon(key)}<span>${label}</span>${key==='word'&&!state.wordUnlocked?'<i class="nav-dot"></i>':''}</a>`).join(''):''}
function home(){let done=state.answers.filter(a=>a.length===2).length;let cards=[['magazine','Experience Guide','Digital Magazine',state.page>1?tr("Halaman ","Page ")+state.page+' / 14':tr("Buka majalah","Open magazine")],['thinking','Thinking Style','Self Discovery',state.assessment?tr("Lihat hasil ✓","View results ✓"):state.thinkingStart?done+tr(" / 15 dijawab"," / 15 answered"):tr("Mulai assessment","Start assessment")],['word','Word Hunt','The Challenge',!state.wordUnlocked?tr("Terkunci","Locked"):state.wordEnd?(repeatInProgress()?tr("Tantangan ulang · ","Repeat challenge · ")+state.wordRepeat.found.length+tr(" kata"," words"):'Mission Accomplished ✓'):state.wordStart?(state.found.length>=10?state.found.length+' / 20':state.found.length+tr(" kata"," words")):tr("Siap dimulai","Ready to begin")]];app.innerHTML=`${tr("<div class=\"home-heading\"><p class=\"eyebrow\">NATIONAL SALES MEETING · 04 DESEMBER 2026</p><h1>Manunggal<span>.</span></h1><p class=\"tag\">Different Minds, Shared Purpose.</p></div><figure class=\"home-photo\"><img src=\"assets/hero.webp\" alt=\"Tangan membuka peta perjalanan Borobudur\"></figure><div class=\"welcome\"><div><p class=\"welcome-name\">Selamat datang, ","<div class=\"home-heading\"><p class=\"eyebrow\">NATIONAL SALES MEETING · 04 DECEMBER 2026</p><h1>Manunggal<span>.</span></h1><p class=\"tag\">Different Minds, Shared Purpose.</p></div><figure class=\"home-photo\"><img src=\"assets/hero.webp\" alt=\"Hands unfolding the Borobudur journey map\"></figure><div class=\"welcome\"><div><p class=\"welcome-name\">Welcome, ")}${name()}${tr(".</p><p class=\"small\">Perjalanan kita dimulai di sini.</p></div><span class=\"team-chip\">TIM ",".</p><p class=\"small\">Our journey begins here.</p></div><span class=\"team-chip\">TEAM ")}${String(state.person.team).padStart(2,'0')}</span></div><div class="row spread section-label"><p class="eyebrow">YOUR EXPERIENCE</p><span class="small">01 — 03</span></div><div class="app-modules">${cards.map(([key,title,sub,progress])=>`<a class="app-tile" href="#${key}">${icon(key)}<strong>${title}</strong><small>${sub}</small><span class="tile-status ${key==='word'&&!state.wordUnlocked?'locked':''}">${key==='word'&&!state.wordUnlocked?icon('lock'):''}${progress}</span></a>`).join('')}</div><div class="home-meta"><button id="openProfile" class="profile-link">${icon('user')}${tr(" Profil peserta</button></div><p class=\"credit\">An experience designed by <b>MOTU Consulting</b></p>"," Participant profile</button></div><p class=\"credit\">An experience designed by <b>MOTU Consulting</b></p>")}`;$('#openProfile').onclick=()=>go('profile')}
function thinkingIntro(){thinkingScreen='intro';app.innerHTML=nav('02 / Discover')+`<article class="panel narrow intro"><div class="intro-banner">${icon('thinking')}${tr("<p class=\"eyebrow\">MANUNGGAL / SELF DISCOVERY</p><h2>Discover How You Think.</h2><p class=\"tag\">Understanding yourself is the beginning of understanding others.</p></div><h2>Inventori Gaya Berpikir</h2><p>Setiap orang memiliki cara yang berbeda dalam memahami informasi, melihat suatu situasi, mengambil keputusan, dan menyelesaikan permasalahan.</p><p>Perbedaan tersebut bukan tentang siapa yang lebih baik, melainkan tentang bagaimana setiap individu memiliki kecenderungan dan kekuatannya masing-masing.</p><p>Melalui inventori sederhana ini, Anda diajak mengenali preferensi gaya berpikir yang paling sering Anda gunakan dalam kehidupan sehari-hari.</p><div class=\"profile-section\"><h3>Petunjuk pengisian</h3><ol class=\"instructions\"><li>Bacalah setiap pilihan (A, B, C, D) dengan saksama.</li><li>Pilih <b>dua dari empat pilihan</b> yang paling menggambarkan diri Anda.</li><li>Pilih berdasarkan kecenderungan Anda yang sebenarnya, bukan berdasarkan apa yang menurut Anda seharusnya menjadi diri Anda.</li><li>Tidak ada jawaban benar atau salah. Setiap pilihan sama pentingnya.</li><li>Jawablah secara mandiri dan alami, tanpa terlalu lama mempertimbangkan setiap pilihan.</li></ol></div><div class=\"intro-facts\"><div><b>15</b><span>Kelompok pernyataan</span></div><div><b>5–7</b><span>Menit (perkiraan)</span></div></div><p class=\"notice\">Hasil inventori merupakan bahan refleksi, bukan diagnosis psikologis, ukuran kecerdasan, atau penilaian kompetensi.</p><button id=\"startThinking\" class=\"btn full\">","<p class=\"eyebrow\">MANUNGGAL / SELF DISCOVERY</p><h2>Discover How You Think.</h2><p class=\"tag\">Understanding yourself is the beginning of understanding others.</p></div><h2>Thinking Style Inventory</h2><p>Everyone has different ways of understanding information, viewing situations, making decisions, and solving problems.</p><p>These differences are not about who is better, but about each individual's own preferences and strengths.</p><p>This simple inventory invites you to recognise the thinking preferences you use most often in everyday life.</p><div class=\"profile-section\"><h3>Instructions</h3><ol class=\"instructions\"><li>Read each option (A, B, C, D) carefully.</li><li>Select <b>two of the four options</b> that best describe you.</li><li>Choose according to your actual preferences, not according to who you think you should be.</li><li>There are no right or wrong answers. Each option is equally important.</li><li>Answer independently and naturally, without overthinking each choice.</li></ol></div><div class=\"intro-facts\"><div><b>15</b><span>Groups of statements</span></div><div><b>5–7</b><span>Minutes (approx.)</span></div></div><p class=\"notice\">The inventory is intended for reflection, not psychological diagnosis, intelligence measurement, or competence assessment.</p><button id=\"startThinking\" class=\"btn full\">")}${state.assessment?tr("Lihat Hasil Saya","View My Results"):state.thinkingStart?tr("Lanjutkan Assessment","Resume Assessment"):'Start My Discovery'} ${icon('arrow')}</button></article>`;$('#startThinking').onclick=()=>{if(closed())return render();if(state.assessment)return result();state.thinkingStart=state.thinkingStart||now();save();thinking();scrollTo(0,0)}}
function validAccess(value){return String(value).trim()==='MOTU'}
function wordGate(){app.innerHTML=nav('03 / Challenge')+`<section class="gate narrow"><div class="gate-icon">${icon('lock')}${tr("</div><p class=\"eyebrow\">THE CHALLENGE</p><h2>Beyond What We See.</h2><p class=\"tag\">Some discoveries have their own moment.</p><p>Tantangan ini belum dimulai. Fasilitator akan memberikan kode akses ketika waktunya tiba.</p><form id=\"unlockForm\" class=\"gate-form\"><label class=\"field\">Access Code<input id=\"accessCode\" name=\"code\" type=\"password\" placeholder=\"Masukkan kode akses\" autocomplete=\"off\" autocapitalize=\"characters\" required maxlength=\"32\"></label><p id=\"accessError\" class=\"error\" role=\"alert\" hidden>Kode akses belum tepat. Silakan coba kembali.</p><button class=\"btn gold full\">Unlock the Challenge ","</div><p class=\"eyebrow\">THE CHALLENGE</p><h2>Beyond What We See.</h2><p class=\"tag\">Some discoveries have their own moment.</p><p>This challenge has not started yet. Your facilitator will provide the access code when it is time.</p><form id=\"unlockForm\" class=\"gate-form\"><label class=\"field\">Access Code<input id=\"accessCode\" name=\"code\" type=\"password\" placeholder=\"Enter access code\" autocomplete=\"off\" autocapitalize=\"characters\" required maxlength=\"32\"></label><p id=\"accessError\" class=\"error\" role=\"alert\" hidden>Incorrect access code. Please try again.</p><button class=\"btn gold full\">Unlock the Challenge ")}${icon('arrow')}</button></form><p class="small">The discovery awaits.</p></section>`;$('#unlockForm').onsubmit=e=>{e.preventDefault();if(closed())return render();if(!validAccess($('#accessCode').value)){ $('#accessError').hidden=false;return}state.wordUnlocked=true;save();shell();word();scrollTo(0,0)}}
function wordIntro(){app.innerHTML=nav('03 / Challenge')+`<section class="gate narrow"><div class="gate-icon">${icon('word')}${tr("</div><p class=\"eyebrow\">WORD HUNT</p><h2>Beyond What We See.</h2><p class=\"tag\">There is always more than meets the eye.</p><p>Di balik susunan huruf ini, terdapat sejumlah kata yang menunggu untuk ditemukan.</p><div class=\"word-instructions\"><h3>Petunjuk tantangan</h3><p>Temukan kata-kata tersembunyi dalam bahasa Indonesia dan bahasa Inggris. Kata dapat tersusun secara horizontal, vertikal, maupun diagonal, termasuk arah terbalik.</p><p>Geser jari sepanjang kata, atau ketuk huruf awal dan huruf akhir. Kamu dapat berdiskusi dengan anggota tim.</p><p>Amati dengan saksama. Jelajahi setiap kemungkinan.</p></div><button id=\"startWord\" class=\"btn gold full\">Mulai Tantangan ","</div><p class=\"eyebrow\">WORD HUNT</p><h2>Beyond What We See.</h2><p class=\"tag\">There is always more than meets the eye.</p><p>Hidden within this grid are words waiting to be discovered.</p><div class=\"word-instructions\"><h3>Challenge instructions</h3><p>Find hidden words in Indonesian and English. Words may appear horizontally, vertically, or diagonally, in either direction.</p><p>Drag along a word, or tap its first and last letters. Collaborate with your teammates; different perspectives and language abilities can help you discover what others cannot see.</p><p>Look carefully. Explore every possibility.</p></div><button id=\"startWord\" class=\"btn gold full\">Start the Challenge ")}${icon('arrow')}</button></section>`;$('#startWord').onclick=()=>{if(closed())return render();state.wordStart=now();save();sendWord();word();scrollTo(0,0)}}
const makePageTitles=()=>[tr("Sampul depan","Front Cover"),'Different Individuals, Shared Direction','Every Journey Begins Somewhere','How to Experience This Journey','Blind Tower','Secret Code','Magic Rope','Puzzle Project','Painting Project','Water Transfer','Photo Hunt','E.T.I.L','The Purpose Continues',tr("Sampul belakang","Back Cover")];
let pageTitles=makePageTitles();
