const pageAsset=n=>{const p=`assets/${language==='en'?'pages-en':'pages'}/${String(n).padStart(2,'0')}.webp`;return globalThis.MANUNGGAL_ASSETS?.[p]||p};
const pageImg=n=>`<img draggable="false" src="${pageAsset(n)}" alt="${tr('Halaman','Page')} ${n}: ${pageTitles[n-1]}">`;
function spreadEnabled(){return spread&&innerWidth>=620&&innerWidth>innerHeight}
function readerPage(n){return spreadEnabled()&&n>1&&n<14&&n%2?n-1:n}
function pageStep(p,d){if(!spreadEnabled())return p+d;if(d>0)return p===1?2:p===14?14:p+2;return p===14?12:p===2?1:p-2}
function readerHelp(){showDialog('Enjoy Your Reading',tr("<div class=\"reader-guide\"><span>←<small>Ketuk kiri</small></span><span>→<small>Ketuk kanan</small></span></div><p>Geser ke kiri untuk lanjut, ke kanan untuk kembali. Ketuk bagian tengah untuk menyembunyikan atau menampilkan kontrol. Cubit dengan dua jari atau ketuk dua kali untuk memperbesar.</p>","<div class=\"reader-guide\"><span>←<small>Tap left</small></span><span>→<small>Tap right</small></span></div><p>Swipe left to go forward, right to go back. Tap the centre to show or hide controls. Pinch with two fingers or double-tap to zoom.</p>"), tr("Mulai Membaca","Start Reading"),null,()=>{state.readerHelp=true;save()})}
function magazine(){let p=readerPage(state.page||1),dual=spreadEnabled()&&p>1&&p<14,p2=dual?p+1:null;state.page=p;readerBusy=false;app.innerHTML=`<section class="book-reader ${readerControls?'':'controls-hidden'}${tr("\" id=\"bookReader\"><header class=\"book-top\"><a class=\"back-big\" href=\"#home\">← Kembali</a><span>Experience Guide</span><button id=\"readerLanguage\" class=\"reader-language\" aria-label=\"","\" id=\"bookReader\"><header class=\"book-top\"><a class=\"back-big\" href=\"#home\">← Back</a><span>Experience Guide</span><button id=\"readerLanguage\" class=\"reader-language\" aria-label=\"")}${tr('Ganti bahasa','Change language')}">${language.toUpperCase()}${tr("</button><button id=\"contents\" aria-label=\"Daftar isi\">☰</button></header><div class=\"book-stage\" id=\"bookStage\"><div class=\"book-sheet ","</button><button id=\"contents\" aria-label=\"Table of contents\">☰</button></header><div class=\"book-stage\" id=\"bookStage\"><div class=\"book-sheet ")}${dual?'double':''}" id="pages"><div class="page-base">${pageImg(p)}${p2?pageImg(p2):''}${tr("</div></div></div><div class=\"book-bottom\"><div class=\"reader-actions\"><button id=\"prev\" aria-label=\"Halaman sebelumnya\" ","</div></div></div><div class=\"book-bottom\"><div class=\"reader-actions\"><button id=\"prev\" aria-label=\"Previous page\" ")}${p<=1?'disabled':''}>‹</button><span id="pageCount">${p}${p2?'–'+p2:''}${tr(" / 14</span><button id=\"next\" aria-label=\"Halaman selanjutnya\" "," / 14</span><button id=\"next\" aria-label=\"Next page\" ")}${p>=14?'disabled':''}${tr(">›</button><button id=\"zoom\" aria-label=\"Perbesar halaman\">＋</button><button id=\"spread\" aria-label=\"Ubah mode halaman\" ",">›</button><button id=\"zoom\" aria-label=\"Zoom page\">＋</button><button id=\"spread\" aria-label=\"Change page layout\" ")}${innerWidth<620||innerWidth<=innerHeight?'disabled':''}>${spreadEnabled()?'1':'2'}${tr(" hlm</button><button id=\"helpReader\" aria-label=\"Petunjuk membaca\">?</button></div><button id=\"contentsBottom\" class=\"toc-trigger\" aria-label=\"Buka daftar isi\"><span aria-hidden=\"true\">☰</span> Daftar Isi <span class=\"toc-current\">"," pg</button><button id=\"helpReader\" aria-label=\"Reading help\">?</button></div><button id=\"contentsBottom\" class=\"toc-trigger\" aria-label=\"Open table of contents\"><span aria-hidden=\"true\">☰</span> Table of Contents <span class=\"toc-current\">")}${p>=5&&p<=12?tr("Pos ","Station ")+String(p-4).padStart(2,'0')+' · ':''}${pageTitles[p-1]}${p2?' / '+pageTitles[p2-1]:''}${tr("</span><span aria-hidden=\"true\">⌃</span></button><p>Ketuk kiri / kanan atau geser untuk membalik halaman</p></div></section>","</span><span aria-hidden=\"true\">⌃</span></button><p>Tap left / right or swipe to turn the page</p></div></section>")}`;
let stage=$('#bookStage'),sheet=$('#pages'),book=$('#bookReader'),panX=0,panY=0,points=new Map(),gesture=null,lastTap=0,lastX=0,lastY=0,tapTimer=null;
function applyZoom(){sheet.style.transform=`translate(${panX}px,${panY}px) scale(${readerScale})`;stage.classList.toggle('is-zoomed',readerScale>1);$('#zoom').textContent=readerScale>1?'−':'＋'}
function scaleTo(v){readerScale=Math.max(1,Math.min(3,v));if(readerScale===1){panX=panY=0}else{let maxX=sheet.offsetWidth*(readerScale-1)/2,maxY=sheet.offsetHeight*(readerScale-1)/2;panX=Math.max(-maxX,Math.min(maxX,panX));panY=Math.max(-maxY,Math.min(maxY,panY))}applyZoom()}
function toggleControls(){readerControls=!readerControls;book.classList.toggle('controls-hidden',!readerControls)}
function change(n,animated=true){n=readerPage(Math.max(1,Math.min(14,n)));if(n===p||readerBusy)return;clearTimeout(tapTimer);readerScale=1;panX=panY=0;applyZoom();state.page=n;save();let nd=spreadEnabled()&&n>1&&n<14,d=n>p?1:-1;if(!animated||matchMedia('(prefers-reduced-motion: reduce)').matches){magazine();return}readerBusy=true;let leaf=document.createElement('div');leaf.className=`turn-leaf ${d>0?'forward':'backward'} ${dual&&nd?'half':'whole'}`;let front=dual&&d>0?p2:p,back=dual&&nd?(d>0?n:n+1):n;
if(dual&&nd){sheet.querySelector('.page-base').innerHTML=d>0?pageImg(p)+pageImg(n+1):pageImg(n)+pageImg(p2)}else{sheet.querySelector('.page-base').innerHTML=pageImg(n);sheet.querySelector('.page-base').classList.add('single-transition')}
leaf.innerHTML=`<div class="leaf-face front">${pageImg(front)}</div><div class="leaf-face rear">${pageImg(back)}</div>`;sheet.append(leaf);let complete=()=>{if(route()==='magazine'&&!closed()&&book.isConnected){readerBusy=false;magazine()}};leaf.addEventListener('animationend',complete,{once:true});setTimeout(complete,780)}
$('#prev').onclick=()=>change(pageStep(p,-1));$('#next').onclick=()=>change(pageStep(p,1));$('#zoom').onclick=()=>scaleTo(readerScale>1?1:2);$('#spread').onclick=()=>{spread=!spread;readerScale=1;magazine()};$('#helpReader').onclick=readerHelp;function openContents(){showDialog(tr("Daftar Isi","Table of Contents"),tr("<p class=\"toc-intro\">Pilih halaman atau tantangan yang ingin Anda buka.</p>","<p class=\"toc-intro\">Select the page or challenge you wish to open.</p>")+tocMarkup(p,p2),tr("Tutup","Close"),null);let dlg=$('#appDialog');dlg.classList.add('bottom-sheet');document.querySelectorAll('[data-jump]').forEach(el=>el.onclick=()=>{closeDialog();change(+el.dataset.jump,false)});let current=dlg.querySelector('.contents-item.current');if(current)current.scrollIntoView({block:'nearest'})}$('#readerLanguage').onclick=switchLanguage;$('#contents').onclick=openContents;$('#contentsBottom').onclick=openContents;
function distance(){let a=[...points.values()];return Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y)}
stage.onpointerdown=e=>{if(readerBusy||e.button!==0)return;stage.setPointerCapture(e.pointerId);points.set(e.pointerId,{x:e.clientX,y:e.clientY});if(points.size===1)gesture={x:e.clientX,y:e.clientY,panX,panY,kind:'single'};if(points.size===2){clearTimeout(tapTimer);gesture={kind:'pinch',distance:distance(),scale:readerScale}}};stage.onpointermove=e=>{if(!points.has(e.pointerId)||!gesture)return;points.set(e.pointerId,{x:e.clientX,y:e.clientY});if(points.size===2&&gesture.kind==='pinch')scaleTo(gesture.scale*distance()/Math.max(1,gesture.distance));else if(points.size===1&&gesture.kind==='single'&&readerScale>1){panX=gesture.panX+e.clientX-gesture.x;panY=gesture.panY+e.clientY-gesture.y;scaleTo(readerScale)}};stage.onpointerup=e=>{if(!points.has(e.pointerId))return;points.delete(e.pointerId);let g=gesture;if(points.size){gesture={kind:'pinch'};return}gesture=null;if(!g||g.kind!=='single')return;let dx=e.clientX-g.x,dy=e.clientY-g.y;if(Math.hypot(dx,dy)>40){if(readerScale===1&&Math.abs(dx)>Math.abs(dy)*1.15)change(pageStep(p,dx<0?1:-1));return}if(Math.hypot(dx,dy)>12)return;let t=Date.now();if(t-lastTap<320&&Math.hypot(e.clientX-lastX,e.clientY-lastY)<45){clearTimeout(tapTimer);lastTap=0;scaleTo(readerScale>1?1:2);return}lastTap=t;lastX=e.clientX;lastY=e.clientY;tapTimer=setTimeout(()=>{if(!book.isConnected)return;let bounds=stage.getBoundingClientRect(),rel=(e.clientX-bounds.left)/bounds.width;if(readerScale>1||rel>=.30&&rel<=.70)toggleControls();else change(pageStep(p,rel>.70?1:-1))},330)};stage.onpointercancel=()=>{points.clear();gesture=null};
applyZoom();for(let i of [p-1,p+1,p+2,p+3])if(i>=1&&i<=14){let img=new Image();img.src=pageAsset(i)}if(!state.readerHelp)readerHelp();}

function thinking(){thinkingScreen='questions';if(state.assessment)return result();if(!state.thinkingStart)return thinkingIntro();let q=state.question,a=state.answers[q];app.innerHTML=nav('02 / Discover')+`<section class="panel narrow question-panel"><div class="row spread"><p class="eyebrow">Thinking Style Assessment</p><span class="small">${q+1} / 15</span></div><div class="progress"><i style="width:${(q+1)/15*100}${tr("%\"></i></div><h2>Manakah yang paling menggambarkan diri Anda?</h2><p>Pilih tepat dua karakteristik yang paling sesuai dengan diri Anda. Tidak ada jawaban benar atau salah.</p><div class=\"choices\">","%\"></i></div><h2>Which characteristics best describe you?</h2><p>Select exactly two characteristics that best describe you. There are no right or wrong answers.</p><div class=\"choices\">")}${(language==='en'?EN_QUESTIONS:DATA.questions)[q].map((t,i)=>`<button class="choice" data-choice="${i}" aria-pressed="${a.includes(i)}"><b>${'ABCD'[i]}</b>${esc(t)}</button>`).join('')}</div><div class="row spread"><span class="small" id="choiceCount">${a.length}${tr(" dari 2 pilihan</span><span class=\"small\">Jawab sesuai diri Anda saat ini.</span></div><div class=\"row spread\" style=\"margin-top:18px\"><button id=\"backQ\" class=\"btn secondary\" "," of 2 selected</span><span class=\"small\">Answer according to who you are today.</span></div><div class=\"row spread\" style=\"margin-top:18px\"><button id=\"backQ\" class=\"btn secondary\" ")}${q===0?'disabled':''}${tr(">← Sebelumnya</button><button id=\"nextQ\" class=\"btn\" ",">← Previous</button><button id=\"nextQ\" class=\"btn\" ")}${a.length!==2?'disabled':''}>${q===14?tr("Lihat hasil","View results"):tr("Selanjutnya","Next")} →</button></div></section>`;document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{let i=+b.dataset.choice;if(a.includes(i))a.splice(a.indexOf(i),1);else if(a.length<2)a.push(i);else return toast(tr("Pilih dua saja. Batalkan salah satu pilihan.","Select only two. Deselect one option first."));save();document.querySelectorAll('[data-choice]').forEach(el=>el.setAttribute('aria-pressed',String(a.includes(+el.dataset.choice))));$('#choiceCount').textContent=a.length+tr(" dari 2 pilihan"," of 2 selected");$('#nextQ').disabled=a.length!==2});$('#backQ').onclick=()=>{state.question--;save();thinking()};$('#nextQ').onclick=()=>{if(closed())return render();if(a.length!==2)return;if(q<14){state.question++;save();thinking();scrollTo(0,0)}else{try{let v=score(state.answers);state.assessment={scores:v,started:state.thinkingStart,ended:now()};save();enqueue('assessment',{answers:state.answers.map(a=>a.slice()),started:state.assessment.started,ended:state.assessment.ended});result();scrollTo(0,0)}catch{toast(tr("Periksa kembali seluruh jawaban.","Please review all your answers."))}}}}
function result(){thinkingScreen='result';let v=state.assessment.scores,p=profile(v),copy=p.copy;app.innerHTML=nav('02 / Discover')+`<article class="panel narrow"><div class="profileHead"><p class="eyebrow">Your personal thinking profile</p><h2>${displayCodes(p.id.replaceAll('+',' + '))}</h2><p>${p.label} · ${name()}</p><p>${p.ix.map(i=>types[i].name).join(' · ')}${tr("</p><small style=\"color:#e5ca96\">Skor tertinggi: ","</p><small style=\"color:#e5ca96\">Highest score: ")}${displayCodes(p.lead)}</small></div><h3>Four ways of thinking</h3><div class="bars">${types.map((t,i)=>`<div><div class="row spread"><span>${t.name} (${displayCodes(t.code)})</span><b>${v[i]}/15</b></div><div class="bar"><i style="width:${v[i]/15*100}%;background:${t.color}"></i></div></div>`).join('')}${tr("</div><p class=\"small\">Total 30 poin. Skor tertinggi dan skor dalam selisih satu poin dikelompokkan sebagai preferensi yang menonjol. Empat skor dalam rentang satu poin disebut relatif seimbang.</p>","</div><p class=\"small\">Total: 30 points. The highest score and scores within one point of it are grouped as prominent preferences. Four scores within one point are considered relatively balanced.</p>")}${['Understanding Your Mind','Your Potential Strengths','Your Growth Opportunities','Your Contribution to the Team'].map((h,i)=>`<section class="profile-section"><h3>${h}</h3><p>${copy[i]}</p></section>`).join('')}<section class="profile-section"><h3>Explore all four styles</h3>${types.map(t=>`<details style="padding:10px 0;border-bottom:1px solid var(--line)"><summary><b>${displayCodes(t.code)} · ${t.name}</b></summary><p>${t.desc}${tr("</p><p><b>Potensi:</b> ","</p><p><b>Potential:</b> ")}${t.strength}${tr("</p><p><b>Pengembangan:</b> ","</p><p><b>Development:</b> ")}${t.growth}</p></details>`).join('')}${tr("</section><p class=\"quote\">We don't need to think alike to move together.</p><p>Bagaimana Anda dapat memanfaatkan cara berpikir Anda sekaligus memberi ruang bagi cara berpikir orang lain?</p><p class=\"small\">Hasil merupakan bahan refleksi diri, bukan diagnosis psikologis, ukuran kecerdasan atau penilaian kompetensi. Batas satu poin merupakan aturan interpretasi kegiatan, bukan ambang psikometrik tervalidasi.</p><button class=\"btn full\" id=\"saveProfile\">Simpan profil sebagai gambar ↓</button><button class=\"link\" id=\"readIntro\">Baca kembali petunjuk</button></article>","</section><p class=\"quote\">We don't need to think alike to move together.</p><p>How can you make the most of your own thinking preferences while making room for the ways others think?</p><p class=\"small\">Results are intended for self-reflection, not psychological diagnosis, intelligence measurement, or competence assessment. The one-point rule is an event-specific interpretation guideline, not a validated psychometric threshold.</p><button class=\"btn full\" id=\"saveProfile\">Save profile as image ↓</button><button class=\"link\" id=\"readIntro\">Review instructions</button></article>")}`;$('#saveProfile').onclick=()=>saveCard(v,p);$('#readIntro').onclick=()=>{thinkingIntro();scrollTo(0,0)}}
function saveCard(v,p){let c=document.createElement('canvas');c.width=1080;c.height=1450;let x=c.getContext('2d');x.fillStyle='#f6f2e9';x.fillRect(0,0,1080,1450);x.fillStyle='#123a44';x.fillRect(0,0,1080,390);x.fillStyle='#e7c789';x.font='bold 25px sans-serif';x.fillText('MANUNGGAL / YOUR THINKING PROFILE',65,70);x.fillStyle='white';x.font='bold 70px Georgia';x.fillText(displayCodes(p.id.replaceAll('+',' + ')),65,170);x.font='34px sans-serif';x.fillText(p.label,65,230);x.font='28px sans-serif';x.fillText(state.person.name.slice(0,48),65,290);x.fillText(tr("Tim ","Team ")+state.person.team,65,335);types.forEach((t,i)=>{let y=455+i*100;x.fillStyle='#123a44';x.font='bold 28px sans-serif';x.fillText(t.name,65,y);x.fillText(v[i]+'/15',920,y);x.fillStyle='#ded6c9';x.fillRect(65,y+20,950,19);x.fillStyle=t.color;x.fillRect(65,y+20,950*v[i]/15,19)});function wrap(text,y){x.fillStyle='#123a44';x.font='29px sans-serif';let l='';for(let w of text.split(' ')){if(x.measureText(l+w).width>940){x.fillText(l,65,y);y+=39;l=''}l+=w+' '}if(l)x.fillText(l,65,y);return y+45}let y=wrap(p.copy[0],900);y=wrap(p.copy[3],y+18);x.font='italic 31px Georgia';x.fillText('Different Minds, Shared Purpose.',65,1330);x.font='22px sans-serif';x.fillText(tr("Bahan refleksi diri · bukan penilaian kompetensi","For self-reflection · not a competence assessment"),65,1380);c.toBlob(async blob=>{if(!blob)return;let file=new File([blob],'Manunggal-Thinking-Profile.png',{type:'image/png'});try{if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:'Your Thinking Profile'});return}}catch(e){if(e.name==='AbortError')return}let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)},'image/png')}
