function activeWord(){return state.wordRepeat?.active?state.wordRepeat:state}
function repeatInProgress(){return !!(state.wordRepeat?.active&&!state.wordRepeat.wordEnd)}
function startRepeat(){if(closed())return render();if(!state.wordEnd||state.found.length!==20)return;ensureCompletionReceipt();state.wordRepeat={active:true,wordStart:now(),wordEnd:null,found:[],finalThree:null};selection=null;drag=null;save();word();scrollTo(0,0)}
function repeatPrompt(){showDialog(tr("Ulangi Tantangan?","Repeat the Challenge?"),tr("<p>Mulai pencarian dari awal pada papan yang sama sebagai latihan pribadi. Pencapaian pertama, durasi, dan catatan Google Sheets tetap dipertahankan. Hasil ulang tidak dikirim ke MOTU.</p>","<p>Start again on the same grid for personal practice. Your first achievement, duration, and Google Sheets record are preserved. Repeat results are not sent to MOTU.</p>"),tr("Batalkan","Cancel"),tr("Ulangi Tantangan","Repeat Challenge"),()=>{},startRepeat)}
