const idx=(r,c)=>r*16+c;
function path(a,b){if(a==null||b==null)return[];let r=Math.floor(a/16),c=a%16,er=Math.floor(b/16),ec=b%16,dr=er-r,dc=ec-c;if(dr&&dc&&Math.abs(dr)!==Math.abs(dc))return[];let n=Math.max(Math.abs(dr),Math.abs(dc));return Array.from({length:n+1},(_,i)=>idx(r+Math.sign(dr)*i,c+Math.sign(dc)*i))}
